import{_ as n,C as s,o as e,c as h,a2 as l,b as i,w as a,a as d,E as p,a3 as o}from"./chunks/framework.CAKCj7G0.js";const k=JSON.parse('{"title":"集合概览","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/集合概览.md","filePath":"Java/Java/集合/集合概览.md","lastUpdated":1762838572000}'),u={name:"Java/Java/集合/集合概览.md"};function c(A,t,E,M,_,g){const r=s("Mermaid");return e(),h("div",null,[t[2]||(t[2]=l('<h1 id="集合概览" tabindex="-1">集合概览 <a class="header-anchor" href="#集合概览" aria-label="Permalink to &quot;集合概览&quot;">​</a></h1><h1 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h1><p>Java 集合框架（Java Collections Framework）是 Java 提供的一套用于存储和操作对象集合的标准体系，它位于 <code>java.util</code> 包中。集合框架为开发者提供了统一的接口和实现，简化了数据结构的使用，提高了代码的可重用性和可维护性。</p><h1 id="二、collection-体系" tabindex="-1">二、Collection 体系 <a class="header-anchor" href="#二、collection-体系" aria-label="Permalink to &quot;二、Collection 体系&quot;">​</a></h1><p>Collection 体系用于存储单列元素，所有实现类都遵循 Collection 接口定义的规范，主要包含 List、Set、Queue、Deque 等子接口。</p>',5)),(e(),i(o,null,{default:a(()=>[p(r,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%8E%A5%E5%8F%A3%20Iterable%5D%20--%3E%20B%5B%E6%8E%A5%E5%8F%A3%20Collection%5D%0A%20%20%20%20B%20--%3E%20C%5B%E6%8E%A5%E5%8F%A3%20List%5D%0A%20%20%20%20B%20--%3E%20D%5B%E6%8E%A5%E5%8F%A3%20Set%5D%0A%20%20%20%20B%20--%3E%20E%5B%E6%8E%A5%E5%8F%A3%20Queue%5D%0A%20%20%20%20E%20--%3E%20F%5B%E6%8E%A5%E5%8F%A3%20Deque%5D%0A%20%20%20%20%0A%20%20%20%20%25%25%20List%20%E5%AE%9E%E7%8E%B0%E7%B1%BB%0A%20%20%20%20C%20--%3E%20ArrayList%0A%20%20%20%20C%20--%3E%20Vector%0A%20%20%20%20C%20--%3E%20CopyOnWriteArrayList%0A%20%20%20%20C%20--%3E%20LinkedList%0A%20%20%20%20%0A%20%20%20%20%25%25%20Set%20%E5%AE%9E%E7%8E%B0%E7%B1%BB%0A%20%20%20%20D%20--%3E%20HashSet%0A%20%20%20%20D%20--%3E%20LinkedHashSet%0A%20%20%20%20D%20--%3E%20TreeSet%0A%20%20%20%20D%20--%3E%20CopyOnWriteArraySet%0A%20%20%20%20%0A%20%20%20%20%25%25%20Queue%20%E5%AE%9E%E7%8E%B0%E7%B1%BB%0A%20%20%20%20E%20--%3E%20PriorityQueue%0A%20%20%20%20E%20--%3E%20ArrayBlockingQueue%0A%20%20%20%20%0A%20%20%20%20%25%25%20Deque%20%E5%AE%9E%E7%8E%B0%E7%B1%BB%EF%BC%88LinkedList%E5%90%8C%E6%97%B6%E5%B1%9E%E4%BA%8EDeque%E5%AE%9E%E7%8E%B0%EF%BC%89%0A%20%20%20%20F%20--%3E%20LinkedList%0A%20%20%20%20F%20--%3E%20ArrayDeque%0A%20%20%20%20F%20--%3E%20LinkedBlockingDeque%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e1f5fe%2Cstroke%3A%230288d1%0A%20%20%20%20style%20B%20fill%3A%23e1f5fe%2Cstroke%3A%230288d1%0A%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=l('<h2 id="_2-1-list-接口" tabindex="-1">2.1 List 接口 <a class="header-anchor" href="#_2-1-list-接口" aria-label="Permalink to &quot;2.1 List 接口&quot;">​</a></h2><p>List 是一个有序的集合，可以包含重复元素，是日常开发中最常用的集合类型之一。</p><p><strong>主要特点</strong>：</p><ul><li><p>元素有序（严格遵循插入顺序）</p></li><li><p>允许存储重复元素</p></li><li><p>支持通过索引（下标）直接访问元素</p></li></ul><p><strong>主要实现类</strong>：</p><ul><li><p><code>ArrayList</code>：基于动态数组实现，查询操作效率高（直接通过索引访问），增删操作效率低（需移动数组元素），是最常用的 List 实现类。</p></li><li><p><code>LinkedList</code>：基于双向链表实现，<strong>同时实现了 List 接口和 Deque 接口</strong>；作为 List 时支持索引访问和重复元素，作为 Deque 时支持双端操作，增删效率高但查询效率低。</p></li><li><p><code>Vector</code>：古老的动态数组实现，线程安全（方法加同步锁），但性能较低，目前已被 ArrayList 替代，仅在遗留系统中可能出现。</p></li><li><p><code>CopyOnWriteArrayList</code>：线程安全的 ArrayList 变体，采用“写时复制”机制，适合读多写少的并发场景，读操作无锁效率高。</p></li></ul><h2 id="_2-2-set-接口" tabindex="-1">2.2 Set 接口 <a class="header-anchor" href="#_2-2-set-接口" aria-label="Permalink to &quot;2.2 Set 接口&quot;">​</a></h2><p>Set 是一个不包含重复元素的集合，元素的存储顺序取决于具体实现类。</p><p><strong>主要特点</strong>：</p><ul><li><p>不允许存储重复元素（基于 equals() 和 hashCode() 方法判断）</p></li><li><p>存储顺序不固定（HashSet）或有序（TreeSet 按自然顺序、LinkedHashSet 按插入顺序）</p></li><li><p>没有索引，无法通过下标访问元素，只能通过迭代器遍历</p></li></ul><p><strong>主要实现类</strong>：</p><ul><li><p><code>HashSet</code>：基于哈希表（HashMap 底层实现），存储无序，查询和增删效率高，是最常用的 Set 实现类。</p></li><li><p><code>LinkedHashSet</code>：继承自 HashSet，内部额外维护双向链表，可保持元素的插入顺序，性能略低于 HashSet。</p></li><li><p><code>TreeSet</code>：基于红黑树（TreeMap 底层实现），元素会按自然顺序或自定义比较器顺序排序，查询和增删效率为 O(log n)。</p></li><li><p><code>CopyOnWriteArraySet</code>：基于 CopyOnWriteArrayList 实现，线程安全，适合读多写少的并发场景，通过元素唯一性保证 Set 特性。</p></li></ul><h2 id="_2-3-queue-接口" tabindex="-1">2.3 Queue 接口 <a class="header-anchor" href="#_2-3-queue-接口" aria-label="Permalink to &quot;2.3 Queue 接口&quot;">​</a></h2><p>Queue 是遵循“先进先出（FIFO）”原则的队列数据结构，主要用于存储待处理的元素序列。</p><p><strong>主要特点</strong>：</p><ul><li><p>默认遵循 FIFO 原则（优先级队列除外）</p></li><li><p>提供队列专用操作方法（如入队 offer()、出队 poll()、查看队首 peek() 等）</p></li><li><p>部分实现类支持阻塞操作（如 ArrayBlockingQueue）</p></li></ul><p><strong>主要实现类</strong>：</p><ul><li><p><code>PriorityQueue</code>：基于优先堆实现的无界队列，元素按优先级排序（自然顺序或自定义比较器），不遵循 FIFO 原则。</p></li><li><p><code>ArrayBlockingQueue</code>：基于数组实现的有界阻塞队列，初始化时需指定容量，支持并发场景下的阻塞入队和出队。</p></li></ul><h2 id="_2-4-deque-接口" tabindex="-1">2.4 Deque 接口 <a class="header-anchor" href="#_2-4-deque-接口" aria-label="Permalink to &quot;2.4 Deque 接口&quot;">​</a></h2><p>Deque 是“双端队列”（Double Ended Queue），允许在队列的两端进行插入和删除操作，兼具队列和栈的特性。</p><p><strong>主要特点</strong>：</p><ul><li><p>支持两端插入（addFirst()/addLast()）和删除（removeFirst()/removeLast()）操作</p></li><li><p>可作为栈使用（push() 入栈、pop() 出栈），也可作为队列使用</p></li></ul><p><strong>主要实现类</strong>：</p><ul><li><p><code>ArrayDeque</code>：基于动态数组实现的双端队列，无容量限制（自动扩容），效率高于 LinkedList，是推荐的双端队列实现。</p></li><li><p><code>LinkedList</code>：基于双向链表实现，<strong>核心实现 List 接口和 Deque 接口</strong>，兼具 List 的有序可重复特性和 Deque 的双端操作能力，可灵活作为列表、队列或栈使用。</p></li><li><p><code>LinkedBlockingDeque</code>：基于链表实现的有界/无界阻塞双端队列，支持并发场景下的阻塞操作。</p></li></ul><h1 id="三、map-体系" tabindex="-1">三、Map 体系 <a class="header-anchor" href="#三、map-体系" aria-label="Permalink to &quot;三、Map 体系&quot;">​</a></h1><p>Map 体系用于存储键值对（Key-Value）映射关系，键具有唯一性，主要包含 SortedMap、ConcurrentMap 等子接口。</p>',26)),(e(),i(o,null,{default:a(()=>[p(r,{id:"mermaid-206",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Map%5BMap%5D%0A%20%20%20%20SortedMap%5BSortedMap%5D%0A%20%20%20%20NavigableMap%5BNavigableMap%5D%0A%20%20%20%20ConcurrentMap%5BConcurrentMap%5D%0A%20%20%20%20%0A%20%20%20%20Map%20--%3E%20SortedMap%0A%20%20%20%20SortedMap%20--%3E%20NavigableMap%0A%20%20%20%20Map%20--%3E%20ConcurrentMap%0A%20%20%20%20%0A%20%20%20%20Map%20--%3E%20HashMap%0A%20%20%20%20Map%20--%3E%20LinkedHashMap%0A%20%20%20%20Map%20--%3E%20Hashtable%0A%20%20%20%20Map%20--%3E%20WeakHashMap%0A%20%20%20%20%0A%20%20%20%20NavigableMap%20--%3E%20TreeMap%0A%20%20%20%20%0A%20%20%20%20ConcurrentMap%20--%3E%20ConcurrentHashMap%0A%20%20%20%20%0A%20%20%20%20style%20Map%20fill%3A%23e1f5fe%2Cstroke%3A%230288d1%0A%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[d(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=l('<h2 id="_3-1-hashmap" tabindex="-1">3.1 HashMap <a class="header-anchor" href="#_3-1-hashmap" aria-label="Permalink to &quot;3.1 HashMap&quot;">​</a></h2><p>基于哈希表（数组+链表+红黑树）实现的 Map，是日常开发中最常用的 Map 实现类。</p><p><strong>核心特点</strong>：</p><ul><li><p>线程不安全，并发场景下需手动同步或使用并发集合</p></li><li><p>允许存储 null 键和 null 值（仅允许一个 null 键）</p></li><li><p>元素存储无序（不保证插入顺序和遍历顺序一致）</p></li><li><p>JDK 8 优化：当链表长度超过阈值（默认 8）时转为红黑树，提高查询效率</p></li></ul><h2 id="_3-2-linkedhashmap" tabindex="-1">3.2 LinkedHashMap <a class="header-anchor" href="#_3-2-linkedhashmap" aria-label="Permalink to &quot;3.2 LinkedHashMap&quot;">​</a></h2><p>继承自 HashMap，内部额外维护双向链表，用于记录元素的插入顺序或访问顺序。</p><p><strong>核心特点</strong>：</p><ul><li><p>保持元素的顺序（默认插入顺序，可通过构造函数指定为访问顺序）</p></li><li><p>查询、增删性能略低于 HashMap（需维护链表结构）</p></li><li><p>允许 null 键和 null 值，线程不安全</p></li><li><p>适合需要保留元素顺序的场景（如缓存的 LRU 策略可通过访问顺序实现）</p></li></ul><h2 id="_3-3-treemap" tabindex="-1">3.3 TreeMap <a class="header-anchor" href="#_3-3-treemap" aria-label="Permalink to &quot;3.3 TreeMap&quot;">​</a></h2><p>基于红黑树实现的 Map，元素会按键（Key）的自然顺序或自定义比较器顺序排序。</p><p><strong>核心特点</strong>：</p><ul><li><p>按键有序（自然排序或自定义 Comparator 排序）</p></li><li><p>不允许 null 键（会抛出 NullPointerException），允许 null 值</p></li><li><p>查询、增删效率为 O(log n)，线程不安全</p></li><li><p>适合需要按键排序的场景（如排行榜、有序统计等）</p></li></ul><h2 id="_3-4-hashtable" tabindex="-1">3.4 Hashtable <a class="header-anchor" href="#_3-4-hashtable" aria-label="Permalink to &quot;3.4 Hashtable&quot;">​</a></h2><p>古老的 Map 实现类，基于哈希表实现，是线程安全的，但目前已基本被 ConcurrentHashMap 替代。</p><p><strong>核心特点</strong>：</p><ul><li><p>线程安全（所有方法加 synchronized 锁），但并发性能低</p></li><li><p>不允许 null 键和 null 值（会抛出 NullPointerException）</p></li><li><p>元素存储无序，JDK 1.0 引入，目前仅在遗留系统中使用</p></li></ul><h2 id="_3-5-concurrenthashmap" tabindex="-1">3.5 ConcurrentHashMap <a class="header-anchor" href="#_3-5-concurrenthashmap" aria-label="Permalink to &quot;3.5 ConcurrentHashMap&quot;">​</a></h2><p>专为高并发场景设计的线程安全 Map 实现类，替代了低效的 Hashtable。</p><p><strong>核心特点</strong>：</p><ul><li><p>高效并发访问：JDK 7 采用分段锁，JDK 8 采用 CAS 算法+ synchronized 锁（仅锁定链表/红黑树头节点）</p></li><li><p>不允许 null 键和 null 值（并发场景下避免空指针歧义）</p></li><li><p>元素存储无序，查询和增删性能接近 HashMap</p></li><li><p>适合多线程并发读写的场景（如分布式系统中的缓存、共享数据存储等）</p></li></ul><h2 id="_3-6-weakhashmap" tabindex="-1">3.6 WeakHashMap <a class="header-anchor" href="#_3-6-weakhashmap" aria-label="Permalink to &quot;3.6 WeakHashMap&quot;">​</a></h2><p>使用弱引用（WeakReference）作为键的 Map，适合实现内存敏感的缓存场景。</p><p><strong>核心特点</strong>：</p><ul><li><p>键采用弱引用：当键不再被其他强引用引用时，会被垃圾回收器回收，对应的键值对也会从 Map 中移除</p></li><li><p>值采用强引用，若需值也随键回收，需手动包装为弱引用</p></li><li><p>线程不安全，适合作为临时缓存（如图片缓存、数据字典缓存等）</p></li></ul><h1 id="四、集合类的比较与选择" tabindex="-1">四、集合类的比较与选择 <a class="header-anchor" href="#四、集合类的比较与选择" aria-label="Permalink to &quot;四、集合类的比较与选择&quot;">​</a></h1><p>不同集合类具有不同的特性，实际开发中需根据业务场景选择合适的集合，以下是核心集合类的对比：</p><table tabindex="0"><thead><tr><th>集合类型</th><th>实现类</th><th>主要特点</th><th>适用场景</th></tr></thead><tbody><tr><td>List（单列有序）</td><td>ArrayList</td><td>动态数组，查询快（O(1)），增删慢（O(n)），线程不安全</td><td>频繁读取、少量插入删除（如数据展示列表、配置项存储）</td></tr><tr><td></td><td>LinkedList</td><td>双向链表，实现 List 和 Deque 接口，有序可重复、增删快（O(1)），查询慢（O(n)）</td><td>频繁插入删除、队列/栈操作（如任务队列、历史记录存储）</td></tr><tr><td>Set（单列不重复）</td><td>HashSet</td><td>哈希表实现，无序，查询/增删快（O(1)），线程不安全</td><td>快速去重、查找（如用户 ID 集合、标签去重）</td></tr><tr><td></td><td>LinkedHashSet</td><td>哈希表+链表，保持插入顺序，性能略低于 HashSet</td><td>需保持插入顺序的去重（如订单号记录、访问记录去重）</td></tr><tr><td></td><td>TreeSet</td><td>红黑树实现，有序（自然/自定义排序），查询/增删 O(log n)</td><td>需排序的去重场景（如成绩排名、优先级任务存储）</td></tr><tr><td>Map（键值对）</td><td>HashMap</td><td>哈希表实现，无序，查询/增删快（O(1)），允许 null 键值</td><td>普通键值对存储（如用户信息缓存、配置映射）</td></tr><tr><td></td><td>LinkedHashMap</td><td>哈希表+链表，保持插入/访问顺序，性能略低于 HashMap</td><td>需保持顺序的键值对（如 LRU 缓存、有序字典）</td></tr><tr><td></td><td>TreeMap</td><td>红黑树实现，按键排序，查询/增删 O(log n)，不允许 null 键</td><td>需按键排序的键值对（如排行榜、有序统计数据）</td></tr><tr><td></td><td>ConcurrentHashMap</td><td>并发安全，高效读写，不允许 null 键值</td><td>多线程并发场景（如分布式缓存、共享配置存储）</td></tr></tbody></table><h1 id="五、集合框架的性能考量" tabindex="-1">五、集合框架的性能考量 <a class="header-anchor" href="#五、集合框架的性能考量" aria-label="Permalink to &quot;五、集合框架的性能考量&quot;">​</a></h1><h2 id="_5-1-时间复杂度" tabindex="-1">5.1 时间复杂度 <a class="header-anchor" href="#_5-1-时间复杂度" aria-label="Permalink to &quot;5.1 时间复杂度&quot;">​</a></h2><p>以下是核心集合类关键操作的时间复杂度对比（n 为集合元素数量）：</p><table tabindex="0"><thead><tr><th>操作类型</th><th>ArrayList</th><th>LinkedList</th><th>HashSet</th><th>TreeSet</th><th>HashMap</th><th>TreeMap</th></tr></thead><tbody><tr><td>随机读取（按索引/键）</td><td>O(1)</td><td>O(n)</td><td>O(1)</td><td>O(log n)</td><td>O(1)</td><td>O(log n)</td></tr><tr><td>插入元素（尾部/随机）</td><td>O(1)（尾部）/O(n)（随机）</td><td>O(1)（两端）/O(n)（随机）</td><td>O(1)</td><td>O(log n)</td><td>O(1)</td><td>O(log n)</td></tr><tr><td>删除元素（尾部/随机）</td><td>O(1)（尾部）/O(n)（随机）</td><td>O(1)（两端）/O(n)（随机）</td><td>O(1)</td><td>O(log n)</td><td>O(1)</td><td>O(log n)</td></tr><tr><td>查找元素（值/键）</td><td>O(n)</td><td>O(n)</td><td>O(1)</td><td>O(log n)</td><td>O(1)</td><td>O(log n)</td></tr></tbody></table><h2 id="_5-2-空间复杂度" tabindex="-1">5.2 空间复杂度 <a class="header-anchor" href="#_5-2-空间复杂度" aria-label="Permalink to &quot;5.2 空间复杂度&quot;">​</a></h2><p>所有核心集合类的空间复杂度均为 O(n)（与元素数量成正比），但不同实现类的额外空间开销不同：</p><ul><li><p><strong>ArrayList</strong>：需预留一定的数组扩容空间（默认扩容为原容量的 1.5 倍），存在一定的空间浪费，但整体开销较小。</p></li><li><p><strong>LinkedList</strong>：每个元素需额外存储前后指针（各 4/8 字节，取决于 JVM 位数），空间开销较大，元素数量越多差距越明显。</p></li><li><p><strong>HashSet/HashMap</strong>：哈希表存在“负载因子”（默认 0.75），需预留空桶以减少哈希冲突，空间利用率约 75%，JDK 8 后红黑树会增加少量节点开销。</p></li><li><p><strong>TreeSet/TreeMap</strong>：红黑树每个节点需存储左右子节点指针和颜色标记，空间开销比哈希表大，约为元素本身大小的 2-3 倍。</p></li><li><p><strong>ConcurrentHashMap</strong>：JDK 8 后引入的节点锁和 CAS 相关标识会增加少量空间开销，整体与 HashMap 接近。</p></li></ul>',34))])}const q=n(u,[["render",c]]);export{k as __pageData,q as default};
